import { VlButtonComponent } from '@domg-wc/components/atom';
import {
    VlMap,
    VlMapBaseLayerGRBGray,
    VlMapFeaturesLayer,
    VlMapLayerCircleStyle,
    VlMapLayerSwitcher,
    VlMapSideSheet,
} from '@domg-wc/map';

// De functies van het codevoorbeeld op de pagina, zonder TypeScript en met de imports uit de packages.
const vlMapSelector = 'vl-map#map-dynamic-layers';

const handleAddLayerForId = (id) => {
    // De kaartlaag verhuist naar de vl-map; de layer-switcher ziet ze verschijnen en voegt een checkbox toe.
    const newLayer = document.querySelector(`vl-map-features-layer#${id}`);
    const vlMap = document.querySelector(vlMapSelector);
    vlMap.appendChild(newLayer);

    const addButton = document.querySelector(`#add-${id}`);
    const toggleButton = document.querySelector(`#toggle-${id}`);
    const removeButton = document.querySelector(`#remove-${id}`);

    toggleButton.hidden = false;
    removeButton.hidden = false;
    addButton.hidden = true;
};

const handleToggleLayerForId = (id) => {
    // layer is de OpenLayers-laag van de vl-map-features-layer.
    const layerToToggle = document.querySelector(`vl-map-features-layer#${id}`);
    const layer = layerToToggle.layer;
    layer.setVisible(!layer.getVisible());
};

const handleRemoveLayerForId = (id) => {
    // De kaartlaag verdwijnt uit de vl-map en uit de layer-switcher; de groep knoppen gaat mee weg.
    const layerToRemove = document.querySelector(`vl-map-features-layer#${id}`);
    const vlMap = document.querySelector(vlMapSelector);
    vlMap.removeChild(layerToRemove);

    const removeButton = document.querySelector(`#remove-${id}`);
    removeButton.parentElement.remove();
};

// Elke kaartlaag krijgt één punt, in Lambert 72 (EPSG:31370), de projectie van deze kaart.
const points = {
    zwart: [149055.0, 199908.0],
    geel: [154055.0, 199908.0],
    rood: [159055.0, 199908.0],
};
for (const [id, coordinates] of Object.entries(points)) {
    document.querySelector(`vl-map-features-layer#${id}`).features = {
        type: 'FeatureCollection',
        features: [{ type: 'Feature', geometry: { type: 'Point', coordinates } }],
    };
    document.querySelector(`#add-${id}`).addEventListener('click', () => handleAddLayerForId(id));
    document.querySelector(`#toggle-${id}`).addEventListener('click', () => handleToggleLayerForId(id));
    document.querySelector(`#remove-${id}`).addEventListener('click', () => handleRemoveLayerForId(id));
}

// Een checkbox van de layer-switcher stuurt vl-change (bubbles en composed) bij elke wijziging van checked. Zet de
// toggle-knop van die kaartlaag gelijk: detail.currentTarget is de vl-checkbox, zijn label de name van de kaartlaag.
document.querySelector(vlMapSelector).addEventListener('vl-change', (event) => {
    const toggleButton = document.querySelector(`vl-button[data-layer="${event.detail?.currentTarget?.label}"]`);
    if (toggleButton) {
        toggleButton.on = event.detail.checked;
    }
});
